#!/usr/bin/env python3
import sys, os, re, gzip, json, csv, datetime
from fractions import Fraction
from decimal import Decimal, ROUND_HALF_UP
import xml.etree.ElementTree as ET

UNIT = {'kg': Fraction(1), 'g': Fraction(1, 1000),
        'lb': Fraction(45359237, 100000000), 'oz': Fraction(28349523125, 1000000000000)}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
COLS = {
    'east': ['id', 'type', 'shipped', 'gross', 'net', 'status', 'note'],
    'harbor': ['rec', 'ref', 'date', 'weight', 'state'],
    'lakeside': ['id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'],
    'river': ['t', 'ref', 'shipped', 'weight', 'status'],
    'west': ['id', 'typ', 'shipped', 'weight', 'status', 'note'],
}
DELIM = {'east': ',', 'harbor': '|', 'lakeside': ',', 'river': '\t', 'west': ';'}
IDCOL = {'east': 'id', 'harbor': 'ref', 'lakeside': 'id', 'river': 'ref', 'west': 'id'}
TYPECOL = {'east': 'type', 'harbor': 'rec', 'lakeside': 'kind', 'river': 't', 'west': 'typ'}
DATECOL = {'east': 'shipped', 'harbor': 'date', 'lakeside': 'shipped', 'river': 'shipped', 'west': 'shipped'}
WCOL = {'east': 'gross', 'harbor': 'weight', 'lakeside': 'gross_kg', 'river': 'weight', 'west': 'weight'}
STCOL = {'east': 'status', 'harbor': 'state', 'lakeside': 'status', 'river': 'status', 'west': 'status'}
BASEDATE = {'east': 'YMD', 'harbor': 'iso', 'lakeside': 'iso', 'river': 'MM/DD/YYYY', 'west': 'DD.MM.YYYY'}
BASEUNIT = {'east': 'kg', 'harbor': 'kg', 'lakeside': 'kg', 'river': 'kg', 'west': 'kg'}
MONTHS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec']


def ptype(s):
    s = (s or '').strip().lower()
    if s in ('c', 'cor', 'corr', 'correction', 'amend'):
        return 'C'
    if s in ('v', 'void'):
        return 'V'
    return 'N'


def norm_status(s):
    return re.sub(r'[\s\-]+', '_', (s or '').strip().lower())


def counted(s):
    return s in ('delivered', 'delivered_late')


def idnum(s):
    m = re.fullmatch(r'\s*SH\D*(\d+)\s*', s or '', re.I)
    return int(m.group(1)) if m else None


def read_text(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if b[:3] == b'\xef\xbb\xbf':
        t = b[3:].decode('utf-8')
    elif b[:2] == b'\xff\xfe':
        t = b[2:].decode('utf-16-le')
    elif b[:2] == b'\xfe\xff':
        t = b[2:].decode('utf-16-be')
    else:
        enc = 'utf-8'
        head = b[:2000].decode('latin-1')
        m = re.search(r'^#\s*charset\s*:\s*([\w.\-]+)', head, re.M | re.I)
        if m:
            enc = m.group(1)
        t = b.decode(enc)
    return t


def parse_date(s, form):
    s = s.strip()
    f = (form or '').strip()
    fl = f.lower()
    if fl == 'serial' or (re.fullmatch(r'\d+(\.\d+)?', s) and fl not in ('yyyymmdd',)):
        return datetime.date(1899, 12, 31) + datetime.timedelta(days=int(float(s)) - 1)
    m = re.match(r'(\d{1,2})\s+([A-Za-z]{3})[a-z]*\s+(\d{4})$', s)
    if m:
        return datetime.date(int(m.group(3)), MONTHS.index(m.group(2).lower()) + 1, int(m.group(1)))
    p = [int(x) for x in re.findall(r'\d+', s)]
    fu = f.upper()
    if fl in ('iso', 'ymd', 'yyyy-mm-dd') or fu == 'YYYY-MM-DD':
        return datetime.date(p[0], p[1], p[2])
    if fu in ('DMY', 'DD-MM-YYYY', 'DD/MM/YYYY', 'DD.MM.YYYY'):
        return datetime.date(p[2], p[1], p[0])
    if fu in ('MM/DD/YYYY', 'MDY'):
        return datetime.date(p[2], p[0], p[1])
    if fu == 'YYYYMMDD' and len(s) == 8:
        return datetime.date(int(s[:4]), int(s[4:6]), int(s[6:]))
    if p and len(str(p[0])) == 4:
        return datetime.date(p[0], p[1], p[2])
    return datetime.date(p[2], p[1], p[0])


def parse_iso_dt(s):
    s = s.strip()
    m = re.match(r'(\d{4})-(\d\d)-(\d\d)(?:[T ](\d\d):(\d\d)(?::(\d\d)(?:\.\d+)?)?\s*(Z|[+-]\d\d:?\d\d|[+-]\d\d)?)?$', s)
    if not m:
        return parse_date(s, 'iso')
    y, mo, d, hh, mm, ss, tz = m.groups()
    dt = datetime.datetime(int(y), int(mo), int(d), int(hh or 0), int(mm or 0), int(ss or 0))
    if tz and tz != 'Z':
        sign = 1 if tz[0] == '+' else -1
        digits = tz[1:].replace(':', '')
        off = datetime.timedelta(hours=int(digits[:2]), minutes=int(digits[2:] or 0))
        dt = dt - sign * off
    return dt.date()


def parse_num(s, decimal_comma=False):
    s = s.strip()
    if decimal_comma:
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    s = s.replace(' ', '')
    return Fraction(Decimal(s))


def weight_kg(text, unit, decimal_comma=False):
    """text may carry its own unit suffix."""
    text = text.strip()
    m = re.fullmatch(r'(.*?)\s*(kg|g|lb|lbs|oz)', text, re.I)
    if m:
        text, unit = m.group(1), m.group(2).lower()
        if unit == 'lbs':
            unit = 'lb'
    return parse_num(text, decimal_comma) * UNIT[unit]


def unit_word(v):
    m = re.match(r'\s*(kg|g|lb|oz)\b', v or '', re.I)
    return m.group(1).lower() if m else None


def read_delimited(depot, path):
    text = read_text(path)
    lines = text.split('\n')
    delim = DELIM[depot]
    cols = set(COLS[depot])
    seq = None
    dform = BASEDATE[depot]
    dunit = None
    header = None
    recs = []
    i = 0
    quoted = delim == ','
    while i < len(lines):
        l = lines[i]
        i += 1
        if l.endswith('\r'):
            l = l[:-1]
        if not l.strip():
            continue
        if l.startswith('\ufeff'):
            l = l[1:]
        if l.startswith('#'):
            body = l[1:].strip()
            m = re.match(r'seq\s*[:=]\s*(\d+)', body, re.I) or re.search(r'\bseq\s*[=:]\s*(\d+)', body, re.I)
            if m:
                seq = int(m.group(1))
                continue
            m = re.match(r'([^:]+?)\s*:\s*(.*)$', body)
            if m:
                name, val = m.group(1).strip().lower(), m.group(2).strip()
                if name in ('dates', 'date format', 'date', 'dateformat'):
                    dform = val
                elif name in ('unit', 'weight unit', 'weight-unit'):
                    u = unit_word(val)
                    if u:
                        dunit = u
            continue
        if quoted:
            while l.count('"') % 2 == 1 and i < len(lines):
                l += '\n' + lines[i]
                i += 1
            row = next(csv.reader([l]))
        else:
            row = l.split(delim)
        if row and all(c.strip() in cols for c in row) and len(row) > 1:
            header = [c.strip() for c in row]
            continue
        if header is None:
            continue
        rowunit = None
        wc = WCOL[depot]
        if wc not in header:
            for c in header:
                if c.startswith('weight') or c.startswith('gross'):
                    wc = c
        if len(row) == len(header) + 1 and wc in header:
            wi = header.index(wc)
            if unit_word(row[wi + 1]):
                rowunit = unit_word(row[wi + 1])
                row = row[:wi + 1] + row[wi + 2:]
        if len(row) != len(header):
            continue
        d = dict(zip(header, row))
        n = idnum(d.get(IDCOL[depot]))
        if n is None:
            continue
        t = ptype(d.get(TYPECOL[depot]))
        rec = {'n': n, 't': t}
        if t != 'V':
            # unit
            colunit = None
            m = re.search(r'_(kg|g|lb|oz)$', wc)
            if m:
                colunit = m.group(1)
            unit = colunit or rowunit or dunit or BASEUNIT[depot]
            rec['kg'] = weight_kg(d[wc], unit, depot == 'west')
            rec['date'] = parse_date(d[DATECOL[depot]], dform)
            rec['status'] = norm_status(d[STCOL[depot]])
        recs.append(rec)
    return seq, recs


HSTATE = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled', 'RET': 'returned', 'HLD': 'held'}


def read_harbor(path):
    seq, recs = read_delimited('harbor', path)
    for r in recs:
        if 'status' in r:
            r['status'] = HSTATE.get(r['status'].upper().replace('_', ''), r['status'])
    return seq, recs


def read_north(path):
    text = read_text(path)
    seq = None
    recs = []
    for l in text.split('\n'):
        l = l.strip().lstrip('\ufeff')
        if not l:
            continue
        v = json.loads(l)
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and 'id' not in o:
                if 'seq' in o['meta'] and seq is None:
                    seq = int(o['meta']['seq'])
                continue
            n = idnum(o.get('id'))
            if n is None:
                continue
            t = ptype(o.get('kind'))
            rec = {'n': n, 't': t}
            if t != 'V':
                wk = [k for k in o if k.startswith('weight_')][0]
                rec['kg'] = Fraction(Decimal(str(o[wk]))) * UNIT[wk[7:].lower()]
                rec['date'] = parse_iso_dt(o['shipped_at'])
                rec['status'] = norm_status(o['status'])
            recs.append(rec)
    return seq, recs


def read_central(path):
    text = read_text(path)
    text = re.sub(r'^\s*<\?xml[^>]*\?>', '', text)
    root = ET.fromstring(text)
    seq = int(root.get('seq')) if root.get('seq') else None
    runit = (root.get('weight-unit') or 'kg').lower()
    recs = []
    for s in root.iter('shipment'):
        def get(name):
            c = s.find(name)
            if c is not None:
                return c
            return s.get(name)
        n = idnum(s.get('id'))
        if n is None:
            continue
        t = ptype(s.get('type'))
        rec = {'n': n, 't': t}
        if t != 'V':
            w = s.find('weight')
            if w is not None:
                wt, wu = w.text, w.get('unit')
            else:
                wt, wu = s.get('weight'), s.get('unit')
            rec['kg'] = weight_kg(wt, (wu or runit).lower())
            sh = s.find('shipped')
            sh = sh.text if sh is not None else s.get('shipped')
            sh = sh.strip()
            rec['date'] = parse_iso_dt(sh) if re.match(r'\d{4}-', sh) else parse_date(sh, '')
            st = s.find('status')
            rec['status'] = norm_status(st.text if st is not None else s.get('status'))
        recs.append(rec)
    return seq, recs


FW = {
    'FW1': dict(len=42, id=(1, 9), type=(10, 10), date=(11, 17), w=(18, 25), st=(26, 26), df='YYYYDDD', unit='g', div=1),
    'FW2': dict(len=43, id=(2, 10), type=(1, 1), date=(11, 18), w=(19, 26), st=(27, 27), df='YYYYMMDD', unit='kg', div=100),
    'FW3': dict(len=41, id=(1, 9), type=(17, 17), date=(10, 16), w=(18, 24), st=(25, 25), df='YYYYDDD', unit='lb', div=10),
}
FWST = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}


def read_south(path):
    text = read_text(path)
    seq = None
    layout = None
    recs = []
    for l in text.split('\n'):
        l = l.rstrip('\r')
        if l.startswith('\x0c') or 'SHIPMENT LISTING' in l:
            continue
        if not l.strip():
            continue
        if l.startswith('#'):
            m = re.match(r'#LAYOUT\s+(\w+)', l)
            if m:
                layout = m.group(1).upper()
            m = re.match(r'#SEQ\s+(\d+)', l)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        lay = layout
        for k, v in FW.items():
            if len(l) == v['len']:
                lay = k
        if lay is None:
            continue
        sp = FW[lay]
        if len(l) < sp['len']:
            l = l.ljust(sp['len'])
        f = lambda k: l[sp[k][0] - 1:sp[k][1]]
        n = idnum(f('id'))
        if n is None:
            continue
        t = ptype(f('type'))
        rec = {'n': n, 't': t}
        if t != 'V':
            ds = f('date')
            if sp['df'] == 'YYYYDDD':
                rec['date'] = datetime.date(int(ds[:4]), 1, 1) + datetime.timedelta(days=int(ds[4:]) - 1)
            else:
                rec['date'] = datetime.date(int(ds[:4]), int(ds[4:6]), int(ds[6:]))
            rec['kg'] = Fraction(int(f('w')), sp['div']) * UNIT[sp['unit']]
            rec['status'] = FWST.get(f('st').strip().upper(), f('st').strip().lower())
        recs.append(rec)
    return seq, recs


def main():
    data, out = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data)):
        p = os.path.join(data, name)
        if not os.path.isfile(p):
            continue
        depot = name.split('-')[0].lower()
        exports.setdefault(depot, [])
        if depot == 'central':
            r = read_central(p)
        elif depot == 'north':
            r = read_north(p)
        elif depot == 'south':
            r = read_south(p)
        elif depot == 'harbor':
            r = read_harbor(p)
        elif depot in DELIM:
            r = read_delimited(depot, p)
        else:
            continue
        exports[depot].append((r[0] if r[0] is not None else 0, name, r[1]))
    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        lst.sort(key=lambda x: x[0])
        for _, _, recs in lst:
            for r in recs:
                n = r['n']
                if r['t'] == 'N':
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r['t'] == 'C':
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur
    seen = {}
    for depot in current:
        for n in current[depot]:
            seen.setdefault(n, []).append(depot)
    handovers = sum(1 for v in seen.values() if len(v) > 1)
    rank = lambda d: ORDER.index(d) if d in ORDER else len(ORDER)
    dep = {d: [0, Fraction(0)] for d in sorted(exports)}
    mon = {}
    for n, ds in seen.items():
        d = min(ds, key=rank)
        r = current[d][n]
        if not counted(r['status']):
            continue
        dep[d][0] += 1
        dep[d][1] += r['kg']
        k = '%04d-%02d' % (r['date'].year, r['date'].month)
        m = mon.setdefault(k, [0, Fraction(0)])
        m[0] += 1
        m[1] += r['kg']

    def rd(fr):
        return float((Decimal(fr.numerator) / Decimal(fr.denominator)).quantize(Decimal('0.01'), ROUND_HALF_UP)) \
            if False else float((Decimal(fr.numerator) * 100 / Decimal(fr.denominator)).to_integral_value(ROUND_HALF_UP) / 100)
    import decimal
    decimal.getcontext().prec = 60
    res = {
        'depots': {d: {'shipments': v[0], 'total_kg': rd(v[1])} for d, v in dep.items()},
        'months': {k: {'shipments': mon[k][0], 'total_kg': rd(mon[k][1])} for k in sorted(mon)},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out, 'w') as f:
        json.dump(res, f, indent=2)


main()
